// html4EntityNameToRune — инверсия html4EntityByRune (имя без &; -> UTF-8).
var html4EntityNameToRune = funcify()

func funcify() map[string]string {
	m := make(map[string]string, len(html4EntityByRune))
	for r, e := range html4EntityByRune {
		if len(e) > 2 && e[0] == '&' && e[len(e)-1] == ';' {
			name := e[1 : len(e)-1]
			if name[0] == '#' {
				continue
			}
			m[name] = string(r)
		}
	}
	return m
}

